window.products.push({"id":1033530,"name":"Butterfly Magic Snow Globe","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/512vMEaF+OL._AC_.jpg","description":"Beautiful butterfly gently perched on a dogwood branch in a snow globe. The base is painted with a wooden texture and a high gloss to offset the scene in the globe. The sculpture inside the globe is hand painted. The snow globe is packaged in a specially designed gift box and included with your purchase of the globe.","images":["https://m.media-amazon.com/images/I/512vMEaF+OL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Feel The Love Designs","source_asin":"B018ENARW0","category_path":"Home & Kitchen"},"sku":"BM-1033530","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B018ENARW0","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B018ENARW0","price_pending":true,"merchant_ready":false});
